(async () => {
  const { env } = await import('node:process');
  const csvPath = env.CSV_PATH;
  const mdPath = env.MARKDOWN_PATH;
  if (!csvPath) throw new Error('Missing CSV_PATH env var');
  if (!mdPath) throw new Error('Missing MARKDOWN_PATH env var');
  globalThis.csvPath = csvPath;
  globalThis.mdPath = mdPath;
})();

(async () => {
  const { parseFile } = await import('fast-csv');
  const { writeFileSync } = await import('node:fs');
  const csvPath = globalThis.csvPath;
  const mdPath = globalThis.mdPath;
  const rows = [];
  await new Promise((resolve, reject) => {
    parseFile(csvPath, { headers: false })
      .on('error', error => reject(error))
      .on('data', row => rows.push(row))
      .on('end', () => resolve());
  });
  if (rows.length === 0) {
    globalThis.markdown = '';
    return;
  }
  const header = rows[0];
  const separator = header.map(() => '---');
  const lines = [];
  lines.push('| ' + header.join(' | ') + ' |');
  lines.push('| ' + separator.join(' | ') + ' |');
  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    lines.push('| ' + row.join(' | ') + ' |');
  }
  const markdown = lines.join('\n');
  writeFileSync(mdPath, markdown);
  globalThis.markdown = markdown;
})();
